public class Main {
    static <T extends Comparable<T>> void insertion_sort(T[] fish) {
        int n = fish.length;
        for (int i = 1; i < n; i++) {
            T hold = fish[i];
            int j = i - 1;
            while (j >= 0 && fish[j].compareTo(hold) > 0) {
                fish[j + 1] = fish[j];
                j--;
            }
            fish[j + 1] = hold;
        }
    }

    public static void main(String[] args) {
        Integer[] fish = {4, 8, 1, 6, 3};
        insertion_sort(fish);
        System.out.print("理牌式：");
        for (int i = 0; i < fish.length; i++) {
            System.out.print(fish[i] + " ");
        }
        System.out.println();
    }
}
